function GREEDY_ANTI_FIB(n_terms):
    terms <- [1]; forbidden <- {}; used <- {1}
    while length(terms) < n_terms:
        if length(terms) >= 2:
            forbidden <- forbidden union { terms[-1] + terms[-2] }
        candidate <- terms[-1] + 1
        while candidate in used or candidate in forbidden:
            candidate <- candidate + 1
        append candidate to terms; add candidate to used
    return terms, forbidden

function ANTI_FIB(k):
    return floor((3*k + 2) / 2)      # integer division

function CONSECUTIVE_SUM(k):
    return ANTI_FIB(k) + ANTI_FIB(k+1)   # equals 3*(k+1)

